import numpy as np
import pandas as pd
from backtesting import Strategy

class GeneratedStrategy(Strategy):
    corr_window = 10
    range_window = 5

    def init(self):
        def alpha_func(close, high, low, volume, corr_window, range_window):
            close_s = pd.Series(close, dtype=float)
            high_s = pd.Series(high, dtype=float)
            low_s = pd.Series(low, dtype=float)
            vol_s = pd.Series(volume).astype(float)

            sign_delta_close = np.sign(close_s.diff(1))
            corr_h_v = high_s.rolling(int(corr_window)).corr(vol_s)
            range_sma = (high_s - low_s).rolling(int(range_window)).mean()

            alpha = sign_delta_close * (-1.0 * corr_h_v) * (1.0 + range_sma / (close_s + 1e-8))
            return alpha.to_numpy()

        self.alpha = self.I(
            alpha_func,
            self.data.Close,
            self.data.High,
            self.data.Low,
            self.data.Volume,
            self.corr_window,
            self.range_window
        )

    def next(self):
        a = self.alpha[-1]
        if np.isnan(a):
            return

        if a > 0:
            if not self.position.is_long:
                if self.position:
                    self.position.close()
                self.buy(size=0.95, sl=self.data.Close[-1] * (1 - 0.02))
        else:
            if self.position.is_long:
                self.position.close()

