class GeneratedStrategy(Strategy):
    sma_window = 12
    return_lookback = 2
    decay_window = 5

    def init(self):
        def alpha_func(close):
            c = pd.Series(close).astype(float)

            sma_c = c.rolling(self.sma_window).mean()
            term1 = (c - sma_c) / (sma_c + 1e-8)

            ret = c.diff(self.return_lookback) / (c.shift(self.return_lookback) + 1e-8)

            d = int(self.decay_window)
            weights = np.arange(1, d + 1, dtype=float)
            wsum = weights.sum() + 1e-8

            def lin_decay(arr):
                return float(np.dot(arr, weights) / wsum)

            term2 = ret.rolling(d).apply(lin_decay, raw=True)

            alpha = term1 + term2
            return alpha.to_numpy()

        self.alpha = self.I(alpha_func, self.data.Close)

    def next(self):
        a = self.alpha[-1]
        if np.isnan(a):
            return

        if a > 0:
            if not self.position.is_long:
                sl = self.data.Close[-1] * (1 - 0.02)
                self.buy(size=0.95, sl=sl)
        else:
            if self.position.is_long:
                self.position.close()

